  // ── Debug Console tab ──
  function _buildConsoleTab(panel, unsubs) {
    var toolbar = document.createElement("div");
    toolbar.className = "_eli3_console_toolbar";

    var allBtn = _filterBtn("All", null, true);
    toolbar.appendChild(allBtn);

    var filterChannel = null;
    var filterBtns = [allBtn];

    function _setFilter(channel, btn) {
      filterChannel = channel;
      filterBtns.forEach(function (b) {
        b.className = "_eli3_filter_btn" + (b === btn ? " _eli3_filter_btn_active" : "");
      });
      _renderRows();
    }
    allBtn.onclick = function () { _setFilter(null, allBtn); };

    var channels = _uniqueChannels();
    channels.forEach(function (ch) {
      var b = _filterBtn(ch, ch, false);
      b.onclick = function () { _setFilter(ch, b); };
      filterBtns.push(b);
      toolbar.appendChild(b);
    });

    var spacer = document.createElement("span");
    spacer.style.flex = "1";
    toolbar.appendChild(spacer);

    var meta = document.createElement("span");
    meta.className = "_eli3_console_meta";
    toolbar.appendChild(meta);

    toolbar.appendChild(eliButton({
      label: "📋 Copy",
      variant: "secondary",
      style: "padding:3px 9px;font:600 10px/1.2 system-ui;",
      onclick: function () { window.eli.log.copyToClipboard(); },
    }));
    toolbar.appendChild(eliButton({
      label: "Clear",
      variant: "secondary",
      style: "padding:3px 9px;font:600 10px/1.2 system-ui;",
      onclick: function () {
        window.eli.log.clear();
        _renderRows();
      },
    }));
    panel.appendChild(toolbar);

    var list = document.createElement("div");
    list.className = "_eli3_log_list";
    panel.appendChild(list);

    function _renderRows() {
      list.innerHTML = "";
      var events = window.eli.log.list();
      if (filterChannel) events = events.filter(function (e) { return e.channel === filterChannel; });
      meta.textContent = events.length + " / " + window.eli.log.MAX_EVENTS + " events";
      if (!events.length) {
        var empty = document.createElement("div");
        empty.className = "_eli3_log_empty";
        empty.textContent = filterChannel ? "No events on '" + filterChannel + "'" : "No events.";
        list.appendChild(empty);
        return;
      }
      events.slice().reverse().forEach(function (ev) { list.appendChild(_renderRow(ev)); });
    }

    // 2026-05-23: redact GitHub repo paths in any URL we display.
    // Screenshots of this Debug tab were exposing owner/repo/branch
    // (e.g., `apndrewn/eli-data/main`). Strip the path between the host
    // and the filename for the known CDN/API surfaces. Keeps the rest of
    // the payload visible for diagnostics.
    function _redactRepoPaths(s) {
      return String(s)
        .replace(/(https?:\/\/raw\.githubusercontent\.com\/)[^/]+\/[^/]+\/[^/]+\//g, "$1.../")
        .replace(/(https?:\/\/cdn\.jsdelivr\.net\/gh\/)[^/@]+\/[^/@]+@[^/]+\//g, "$1.../")
        .replace(/(https?:\/\/api\.github\.com\/repos\/)[^/]+\/[^/]+\//g, "$1.../");
    }
    function _renderRow(ev) {
      var row = document.createElement("div");
      row.className = "_eli3_log_row";
      var t = document.createElement("span");
      t.className = "_eli3_log_time";
      t.textContent = _formatTime(ev.timestamp);
      row.appendChild(t);
      var c = document.createElement("span");
      c.className = "_eli3_log_chan";
      c.textContent = ev.channel;
      row.appendChild(c);
      var m = document.createElement("span");
      m.className = "_eli3_log_msg";
      m.textContent = _redactRepoPaths(ev.name);
      row.appendChild(m);
      if (ev.payload != null) {
        var p = document.createElement("div");
        p.className = "_eli3_log_payload";
        try { p.textContent = _redactRepoPaths(JSON.stringify(ev.payload)); }
        catch (e) { p.textContent = String(ev.payload); }
        row.appendChild(p);
      }
      return row;
    }

    function _formatTime(ts) {
      var d = new Date(ts);
      var pad = function (n) { return n < 10 ? "0" + n : "" + n; };
      return pad(d.getHours()) + ":" + pad(d.getMinutes()) + ":" + pad(d.getSeconds());
    }
    function _uniqueChannels() {
      var out = {};
      window.eli.log.list().forEach(function (e) { out[e.channel] = true; });
      return Object.keys(out).sort();
    }

    _renderRows();
    var unsub = window.eli.log.subscribe(function (entry) {
      var existing = filterBtns.map(function (b) { return b.getAttribute("data-ch"); });
      if (entry.channel && existing.indexOf(entry.channel) === -1) {
        var b = _filterBtn(entry.channel, entry.channel, false);
        b.onclick = function () { _setFilter(entry.channel, b); };
        filterBtns.push(b);
        toolbar.insertBefore(b, spacer);
      }
      _renderRows();
    });
    unsubs.push(unsub);
  }

  function _filterBtn(label, channel, active) {
    var b = document.createElement("span");
    b.className = "_eli3_filter_btn" + (active ? " _eli3_filter_btn_active" : "");
    b.textContent = label;
    if (channel) b.setAttribute("data-ch", channel);
    return b;
  }

  // 2026-05-23: Downloads tab — reads persisted download entries from
  // eli-activity's IDB ring (config store, "activity_feed" key). Only
  // download-typed entries persist across sessions, so this is the only
  // surface that shows historical "what tools/libraries arrived when".
  function _buildDownloadsTab(panel, unsubs) {
    var toolbar = document.createElement("div");
    toolbar.className = "_eli3_console_toolbar";
    var meta = document.createElement("span");
    meta.className = "_eli3_console_meta";
    meta.textContent = "Loading…";
    toolbar.appendChild(meta);
    var spacer = document.createElement("span");
    spacer.style.flex = "1";
    toolbar.appendChild(spacer);
    toolbar.appendChild(eliButton({
      label: "↻ Refresh",
      variant: "secondary",
      style: "padding:3px 9px;font:600 10px/1.2 system-ui;",
      onclick: function () { _load(); },
    }));
    panel.appendChild(toolbar);

    var list = document.createElement("div");
    list.className = "_eli3_log_list";
    panel.appendChild(list);

    function _load() {
      list.innerHTML = "";
      meta.textContent = "Loading…";
      if (!window.eli || !window.eli.storage || typeof window.eli.storage.get !== "function") {
        meta.textContent = "storage unavailable";
        return;
      }
      window.eli.storage.get("config", "activity_feed").then(function (row) {
        var entries = (row && Array.isArray(row.entries)) ? row.entries.slice() : [];
        // Defense-in-depth: filter at read time too. Legacy entries from
        // before the persistence-policy change (when ALL activity types
        // were saved) may still sit in IDB until a fresh download triggers
        // a re-persist + scrub. The eli-activity _persist() function only
        // re-writes the file when at least one download entry exists in
        // the current session ring — so old non-download junk can linger.
        entries = entries.filter(function (e) {
          return e && typeof e.type === "string" && e.type.indexOf("download") === 0;
        });
        // Newest first
        entries.sort(function (a, b) { return (b.timestamp || 0) - (a.timestamp || 0); });
        meta.textContent = entries.length + " download" + (entries.length === 1 ? "" : "s") + " recorded";
        if (!entries.length) {
          var empty = document.createElement("div");
          empty.className = "_eli3_log_empty";
          empty.textContent = "No downloads recorded yet. Tool installs and library updates will appear here as they happen.";
          list.appendChild(empty);
          return;
        }
        entries.forEach(function (e) { list.appendChild(_renderDownloadRow(e)); });
      }).catch(function (err) {
        meta.textContent = "load failed";
        var errBox = document.createElement("div");
        errBox.className = "_eli3_log_empty";
        errBox.textContent = "Failed to read activity feed: " + (err && err.message || "unknown");
        list.appendChild(errBox);
      });
    }

    // Local copy — _formatTime is scoped inside _buildConsoleTab and
    // not visible here. Same hh:mm:ss format for consistency between tabs.
    function _fmtTimeLocal(ts) {
      if (!ts) return "?";
      var d = new Date(ts);
      var pad = function (n) { return n < 10 ? "0" + n : "" + n; };
      return pad(d.getHours()) + ":" + pad(d.getMinutes()) + ":" + pad(d.getSeconds()) +
        " (" + d.toLocaleDateString() + ")";
    }
    function _renderDownloadRow(e) {
      var row = document.createElement("div");
      row.className = "_eli3_log_row";
      var t = document.createElement("span");
      t.className = "_eli3_log_time";
      t.textContent = _fmtTimeLocal(e.timestamp);
      row.appendChild(t);
      var c = document.createElement("span");
      c.className = "_eli3_log_chan";
      c.textContent = (e.icon || "📥") + " " + (e.type || "download");
      row.appendChild(c);
      var m = document.createElement("span");
      m.className = "_eli3_log_msg";
      m.textContent = e.label || e.id || "(unnamed)";
      row.appendChild(m);
      if (e.summary) {
        var p = document.createElement("div");
        p.className = "_eli3_log_payload";
        p.textContent = e.summary;
        row.appendChild(p);
      }
      return row;
    }

    _load();
  }
}


// ─── Wrongness debug viewer (NEW UI) ─────────────────────────────────
// No v2 source — built fresh on top of eli.wrongness.list/getCapture/
// replayCapture/clear/copyToClipboard.
//
// Surface:
//   - Toolbar: tool-id filter dropdown · Copy All · Clear All · count meter
//   - Scrollable list: each row shows {timestamp, toolId, kind (capture|flag), id-hash}
//   - Click a row → expanded detail with provenance + sanitized input/output JSON,
//     plus per-row Replay + Copy buttons.
//
// opts (all optional): {} — viewer reads from window.eli.wrongness.* directly.

view.renderWrongness:
function renderWrongness(/* opts */) {
  if (typeof showEliDialog !== "function") {
    if (typeof showToast === "function") showToast("Wrongness viewer requires showEliDialog", "err");
    return;
  }
  if (!window.eli.wrongness || typeof window.eli.wrongness.list !== "function") {
    if (typeof showToast === "function") showToast("eli.wrongness API unavailable", "err");
    return;
  }

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function _formatTime(ts) {
    if (!ts) return "—";
    var d = new Date(ts);
    var pad = function (n) { return n < 10 ? "0" + n : "" + n; };
    return d.getFullYear() + "-" + pad(d.getMonth() + 1) + "-" + pad(d.getDate()) +
           " " + pad(d.getHours()) + ":" + pad(d.getMinutes()) + ":" + pad(d.getSeconds());
  }
  function _shortId(id) {
    var s = String(id || "");
    var i = s.lastIndexOf("_");
    return i > -1 ? s.slice(i + 1) : s.slice(-6);
  }

  var _filterTool = ""; // "" = all
  var _expandedId = null;
  var _entries = [];
  var _overlayRef = null;

  function _refresh() {
    return window.eli.wrongness.list().then(function (rows) {
      _entries = rows || [];
      if (_overlayRef) _renderBody(_overlayRef);
    }).catch(function (err) {
      if (typeof showToast === "function") showToast("Load failed: " + (err && err.message || "unknown"), "err");
    });
  }

  function _filteredEntries() {
    if (!_filterTool) return _entries;
    return _entries.filter(function (e) { return (e.toolId || "") === _filterTool; });
  }

  function _uniqueToolIds() {
    var s = {};
    _entries.forEach(function (e) { if (e.toolId) s[e.toolId] = true; });
    return Object.keys(s).sort();
  }

  function _renderToolbar(host) {
    host.innerHTML = "";
    var bar = document.createElement("div");
    bar.className = "_eli3_wrong_toolbar";
    bar.style.cssText = "display:flex;gap:6px;align-items:center;flex-wrap:wrap;padding-bottom:8px;border-bottom:1px solid #ececec;margin-bottom:8px";

    var label = document.createElement("span");
    label.style.cssText = "font:600 10px/1 system-ui;color:#5a6368;text-transform:uppercase;letter-spacing:.04em";
    label.textContent = "Tool:";
    bar.appendChild(label);

    var sel = document.createElement("select");
    sel.style.cssText = "font:11px system-ui;padding:2px 6px;border:1px solid #d6dbe1;border-radius:4px";
    var optAll = document.createElement("option");
    optAll.value = "";
    optAll.textContent = "All";
    sel.appendChild(optAll);
    _uniqueToolIds().forEach(function (id) {
      var o = document.createElement("option");
      o.value = id;
      o.textContent = id;
      sel.appendChild(o);
    });
    sel.value = _filterTool;
    sel.onchange = function () { _filterTool = sel.value; _renderBody(_overlayRef); };
    bar.appendChild(sel);

    var spacer = document.createElement("span");
    spacer.style.flex = "1";
    bar.appendChild(spacer);

    var meter = document.createElement("span");
    var filtered = _filteredEntries();
    meter.style.cssText = "font:11px system-ui;color:#5a6368";
    meter.textContent = filtered.length + " / " + _entries.length + " entries (max " + (window.eli.wrongness.MAX_CAPTURES || 50) + ")";
    bar.appendChild(meter);

    bar.appendChild(eliButton({
      label: "📋 Copy Corpus",
      variant: "secondary",
      style: "padding:3px 9px;font:600 10px/1.2 system-ui;",
      onclick: function () { window.eli.wrongness.copyToClipboard(); },
    }));
    bar.appendChild(eliButton({
      label: "Clear All",
      variant: "secondary",
      style: "padding:3px 9px;font:600 10px/1.2 system-ui;",
      onclick: function () {
        if (!_entries.length) return;
        if (window.eli.ui && typeof window.eli.ui.confirm === "function") {
          window.eli.ui.confirm({
            title: "Clear all wrongness captures?",
            message: "This deletes all " + _entries.length + " captures and flags from IDB. Cannot be undone.",
            confirmLabel: "Clear All",
            destructive: true,
          }).then(function (ok) {
            if (!ok) return;
            window.eli.wrongness.clear().then(_refresh);
          });
        } else {
          window.eli.wrongness.clear().then(_refresh);
        }
      },
    }));

    host.appendChild(bar);
  }

  function _renderList(host) {
    var filtered = _filteredEntries();
    if (!filtered.length) {
      var empty = document.createElement("div");
      empty.style.cssText = "padding:30px 16px;text-align:center;color:#7f8c8d;font:12px system-ui";
      empty.textContent = _filterTool
        ? "No entries for tool '" + _filterTool + "'."
        : "No wrongness captures yet. Tools call eli.wrongness.capture() after each engine run.";
      host.appendChild(empty);
      return;
    }
    var listEl = document.createElement("div");
    listEl.className = "_eli3_wrong_list";
    listEl.style.cssText = "display:flex;flex-direction:column;gap:4px;max-height:420px;overflow-y:auto";

    filtered.forEach(function (entry) {
      var ts = entry.capturedAt || entry.flaggedAt;
      var isFlag = entry.kind === "flag";
      var row = document.createElement("div");
      row.className = "_eli3_wrong_row";
      row.style.cssText = "border:1px solid #ececec;border-radius:6px;background:#fafbfc;font:11px/1.4 system-ui";

      var head = document.createElement("div");
      head.style.cssText = "display:flex;gap:10px;align-items:center;padding:6px 10px;cursor:pointer";
      head.onclick = function () {
        _expandedId = (_expandedId === entry.id) ? null : entry.id;
        _renderBody(_overlayRef);
      };

      var kindBadge = document.createElement("span");
      kindBadge.style.cssText = "font:600 9px/1 system-ui;letter-spacing:.04em;padding:2px 5px;border-radius:3px;text-transform:uppercase;color:#fff;background:" + (isFlag ? "#c0392b" : "#3498db");
      kindBadge.textContent = isFlag ? "Flag" : "Capture";
      head.appendChild(kindBadge);

      var tid = document.createElement("span");
      tid.style.cssText = "font:600 11px system-ui;color:#2c3e50";
      tid.textContent = entry.toolId || "(no toolId)";
      head.appendChild(tid);

      var time = document.createElement("span");
      time.style.cssText = "color:#7f8c8d;font:11px system-ui";
      time.textContent = _formatTime(ts);
      head.appendChild(time);

      var spacer = document.createElement("span");
      spacer.style.flex = "1";
      head.appendChild(spacer);

      var idTag = document.createElement("span");
      idTag.style.cssText = "color:#95a5a6;font:10px monospace";
      idTag.textContent = "#" + _shortId(entry.id);
      head.appendChild(idTag);

      var caret = document.createElement("span");
      caret.style.cssText = "color:#7f8c8d;font:10px monospace;width:10px;text-align:right";
      caret.textContent = (_expandedId === entry.id) ? "▾" : "▸";
      head.appendChild(caret);

      row.appendChild(head);

      if (_expandedId === entry.id) {
        var detail = document.createElement("div");
        detail.style.cssText = "padding:8px 10px;border-top:1px solid #ececec;background:#fff";

        if (isFlag) {
          if (entry.findingId) {
            detail.appendChild(_kvLine("Finding ID", entry.findingId));
          }
          if (entry.note) {
            detail.appendChild(_kvLine("Note", entry.note));
          }
        }
        if (entry.provenance) {
          var provBlock = document.createElement("div");
          provBlock.style.cssText = "margin-top:6px";
          var pTitle = document.createElement("div");
          pTitle.style.cssText = "font:600 10px/1 system-ui;color:#5a6368;margin-bottom:4px;text-transform:uppercase;letter-spacing:.04em";
          pTitle.textContent = "Provenance";
          provBlock.appendChild(pTitle);
          var pre = document.createElement("pre");
          pre.style.cssText = "margin:0;padding:6px 8px;background:#f4f6f8;border-radius:4px;font:10px/1.4 monospace;white-space:pre-wrap;word-break:break-all;max-height:120px;overflow-y:auto";
          try { pre.textContent = JSON.stringify(entry.provenance, null, 2); }
          catch (e) { pre.textContent = "(unstringifiable)"; }
          provBlock.appendChild(pre);
          detail.appendChild(provBlock);
        }
        if (!isFlag) {
          detail.appendChild(_jsonBlock("Input (sanitized)", entry.input));
          detail.appendChild(_jsonBlock("Output (sanitized)", entry.output));
        }

        var actions = document.createElement("div");
        actions.style.cssText = "display:flex;gap:6px;margin-top:8px;flex-wrap:wrap";
        if (!isFlag) {
          actions.appendChild(eliButton({
            label: "▶ Replay",
            variant: "secondary",
            style: "padding:3px 9px;font:600 10px/1.2 system-ui;",
            onclick: function () {
              window.eli.wrongness.replayCapture(entry.id).then(function (res) {
                if (typeof showToast === "function") showToast("Replay finished in " + res.ms + "ms — see console", "ok");
                if (window.eli.log && window.eli.log.event) {
                  window.eli.log.event("wrongness", "replay_done", { captureId: entry.id, ms: res.ms });
                }
              }).catch(function (err) {
                if (typeof showToast === "function") showToast("Replay failed: " + (err && err.message || "unknown"), "err");
              });
            },
          }));
        }
        actions.appendChild(eliButton({
          label: "📋 Copy Entry",
          variant: "secondary",
          style: "padding:3px 9px;font:600 10px/1.2 system-ui;",
          onclick: function () {
            var json;
            try { json = JSON.stringify(entry, null, 2); }
            catch (e) { json = "(unstringifiable entry)"; }
            if (window.eli.ui && typeof window.eli.ui.copyText === "function") {
              window.eli.ui.copyText(json, "Wrongness entry " + _shortId(entry.id));
            } else if (typeof showToast === "function") {
              showToast("Copy unavailable (eli.ui.copyText missing)", "err");
            }
          },
        }));
        detail.appendChild(actions);
        row.appendChild(detail);
      }

      listEl.appendChild(row);
    });

    host.appendChild(listEl);
  }

  function _kvLine(label, value) {
    var row = document.createElement("div");
    row.style.cssText = "display:flex;gap:8px;font:11px system-ui;margin-top:4px";
    var l = document.createElement("span");
    l.style.cssText = "font:600 10px/1.4 system-ui;color:#5a6368;min-width:80px;text-transform:uppercase;letter-spacing:.04em";
    l.textContent = label;
    var v = document.createElement("span");
    v.style.cssText = "color:#2c3e50;word-break:break-all";
    v.textContent = String(value == null ? "" : value);
    row.appendChild(l);
    row.appendChild(v);
    return row;
  }

  function _jsonBlock(title, value) {
    var block = document.createElement("div");
    block.style.cssText = "margin-top:6px";
    var t = document.createElement("div");
    t.style.cssText = "font:600 10px/1 system-ui;color:#5a6368;margin-bottom:4px;text-transform:uppercase;letter-spacing:.04em";
    t.textContent = title;
    block.appendChild(t);
    var pre = document.createElement("pre");
    pre.style.cssText = "margin:0;padding:6px 8px;background:#f4f6f8;border-radius:4px;font:10px/1.4 monospace;white-space:pre-wrap;word-break:break-all;max-height:200px;overflow-y:auto";
    try { pre.textContent = (value == null) ? "(none)" : JSON.stringify(value, null, 2); }
    catch (e) { pre.textContent = "(unstringifiable)"; }
    block.appendChild(pre);
    return block;
  }

  function _renderBody(overlay) {
    if (!overlay) return;
    var desc = overlay.querySelector(".eli-dialog-desc");
    if (!desc) return;
    desc.innerHTML = '<div id="_eli3_wrong_root"></div>';
    var root = desc.querySelector("#_eli3_wrong_root");
    _renderToolbar(root);
    _renderList(root);
  }

  showEliDialog({
    variant: "neutral",
    icon: "🐞",
    title: "Wrongness Debug Viewer",
    body: '<div id="_eli3_wrong_root">Loading…</div>',
    secondary: { label: "Close" },
    onMount: function (overlay) {
      _overlayRef = overlay;
      var panelEl = overlay.querySelector(".eli-dialog");
      if (panelEl) panelEl.className += " _eli3_dialog_wide";
      _refresh();
    },
  });
}

// ─── Cancelled screen ─────────────────────────────────────────────────
// Premium full-screen overlay shown when the kernel FSM transitions to
// "cancelled". Subscribed via eli.bus.on("fsm:transition", ...) in
// init.js so the kernel stays untouched — this is pure tool reaction
// to a public event. Idempotent: if the overlay is already mounted, no
// double-paint. The "Go Home" button calls eli.dashboard.goHome() and
// removes the overlay; the kernel's separate auto-transition back to
// idle doesn't affect the overlay's lifecycle (DOM-driven, not FSM-driven).

view.renderCancelledScreen:
function renderCancelledScreen(opts) {
  opts = opts || {};
  var existing = document.getElementById("_eli3_cancelled_screen");
  if (existing) return existing;
  var ov = document.createElement("div");
  ov.id = "_eli3_cancelled_screen";
  ov.className = "_eli3_cancelled_overlay";
  ov.innerHTML =
    '<div class="_eli3_cancelled_card">' +
      '<div class="_eli3_cancelled_iconwrap"><span class="_eli3_cancelled_icon">⏹</span></div>' +
      '<div class="_eli3_cancelled_eyebrow">Action Cancelled</div>' +
      '<div class="_eli3_cancelled_title">You stopped the run</div>' +
      '<div class="_eli3_cancelled_subtitle">' +
        'Nothing was applied to the document. Head back to the dashboard and try again whenever you\'re ready.' +
      '</div>' +
      '<button type="button" class="_eli3_cancelled_btn" id="_eli3_cancelled_home_btn">' +
        '<span class="_eli3_cancelled_btn_icon">🏠</span>' +
        '<span>Go Home</span>' +
      '</button>' +
    '</div>';
  document.body.appendChild(ov);
  var btn = ov.querySelector("#_eli3_cancelled_home_btn");
  if (btn) {
    btn.onclick = function () {
      // Remove ourselves first so the dashboard repaint underneath us
      // doesn't fight against an overlay-on-top during goHome.
      if (ov.parentNode) ov.parentNode.removeChild(ov);
      if (typeof opts.onGoHome === "function") {
        try { opts.onGoHome(); } catch (_) {}
      } else if (window.eli && window.eli.dashboard && typeof window.eli.dashboard.goHome === "function") {
        try { window.eli.dashboard.goHome(); } catch (_) {}
      }
    };
  }
  // Esc key dismiss (same as Go Home — quick keyboard escape).
  function _onKey(e) {
    if (e.key === "Escape" || e.keyCode === 27) {
      if (btn) btn.click();
      document.removeEventListener("keydown", _onKey, true);
    }
  }
  document.addEventListener("keydown", _onKey, true);
  return ov;
}

jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };
  var bundle = eli.tools._loaded["eli_kit"];
  if (!bundle) return;

  // ─── Install full clipboard helper (kernel had only direct-write stub) ──
  // 2026-05-12 offload from kernel §16.9. Replaces window._eliClipboardWriteOrFallback
  // with the focus-fallback dialog. Kernel stub stays as the boot-time
  // fallback so anything that calls before eli_kit loads gets at least
  // navigator.clipboard.writeText (no UI).
  window._eliClipboardWriteOrFallback = function (text, label) {
    if (typeof navigator !== "undefined" && navigator.clipboard && navigator.clipboard.writeText) {
      return navigator.clipboard.writeText(text).catch(function () {
        _eliKitShowCopyFallback(text, label);
      });
    }
    _eliKitShowCopyFallback(text, label);
    return Promise.resolve();
  };
  function _eliKitShowCopyFallback(text, label) {
    if (typeof showEliDialog !== "function") return;
    var safe = String(text || "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
    var taId = "_eli3_copy_ta_" + Date.now();
    showEliDialog({
      variant: "info",
      icon: "📋",
      title: label || "Copy to clipboard",
      body:
        '<div class="_eli3_copy_hint">Auto-selected. Press <b>Ctrl+C</b> (or <b>⌘C</b> on Mac) to copy, then paste in chat.</div>' +
        '<textarea id="' + taId + '" readonly class="_eli3_copy_textarea">' + safe + '</textarea>',
      buttons: [{
        label: "Try direct copy",
        onclick: function (e, ov) {
          try {
            if (navigator && navigator.clipboard && navigator.clipboard.writeText) {
              navigator.clipboard.writeText(text).then(function () {
                if (typeof showToast === "function") showToast("Copied to clipboard.", "ok");
                if (ov.parentNode) ov.parentNode.removeChild(ov);
              }).catch(function () {
                if (typeof showToast === "function") showToast("Direct copy still blocked. Use Ctrl+C from textarea.", "warn");
              });
            }
          } catch (e2) {}
        },
      }, {
        label: "Done",
        cls: "btn-secondary",
        onclick: function (e, ov) { if (ov.parentNode) ov.parentNode.removeChild(ov); },
      }],
      onMount: function (ov) {
        setTimeout(function () {
          var ta = ov.querySelector("#" + taId);
          if (ta) {
            try { ta.focus(); ta.select(); } catch (e) {}
          }
        }, 80);
      },
    });
  }
  var vfns = bundle._eliViewFns || {};
  var renderCustomize = vfns.renderCustomize;
  var renderTabbedDialog = vfns.renderTabbedDialog;
  var renderWrongness = vfns.renderWrongness;
  var renderCancelledScreen = vfns.renderCancelledScreen;
  if (!renderCustomize || !renderTabbedDialog || !renderWrongness) {
    eli.log.event("tool", "eli_kit_load_failed", {
      hasCustomize: !!renderCustomize,
      hasTabbedDialog: !!renderTabbedDialog,
      hasWrongness: !!renderWrongness,
    });
    return;
  }

  // ── Cancelled screen — paints when FSM hits "cancelled" ─────────
  // 2026-05-16 fix: kernel setLoading(false) does scanning → cancelled
  // → idle as routine post-scan cleanup, NOT a user cancel. Both
  // transitions fire bus events synchronously, so a naive "to ===
  // cancelled" check paints the screen after every completed scan.
  // Defer the paint ~120ms; if FSM has moved to idle by then it was
  // kernel cleanup → skip. Real user cancellations (showCancelledState)
  // sit at "cancelled" for ~1.2s so they still trigger the paint.
  // Idempotent — renderCancelledScreen no-ops if already mounted.
  if (renderCancelledScreen && eli.bus && typeof eli.bus.on === "function") {
    eli.log.event("tool", "cancelled_screen_subscribed", {});
    eli.bus.on("fsm:transition", function (payload) {
      var to = payload && payload.to;
      eli.log.event("tool", "cancelled_screen_observed_transition", {
        from: payload && payload.from, to: to,
      });
      if (!payload || payload.to !== "cancelled") return;
      setTimeout(function () {
        var cur = (eli.fsm && typeof eli.fsm.current === "function") ? eli.fsm.current() : "(no fsm)";
        eli.log.event("tool", "cancelled_screen_timeout_fired", {
          fsmAt120ms: cur, willPaint: cur === "cancelled",
        });
        try {
          if (cur !== "cancelled") return;
          renderCancelledScreen();
          eli.log.event("tool", "cancelled_screen_painted", {});
        } catch (e) {
          eli.log.event("tool", "cancelled_screen_render_failed", { msg: e && e.message });
        }
      }, 120);
    });
    // Console test handle — `eli.kit.testCancelDialog()` paints the
    // screen directly, bypassing FSM. Lets us isolate "is the dialog
    // wiring broken?" from "is the trigger chain broken?".
    if (!eli.kit) eli.kit = {};
    eli.kit.testCancelDialog = function () { return renderCancelledScreen(); };
  }

  // ── Customize Dashboard ─────────────────────────────────────────
  function openCustomize() {
    if (!eli.dashboard ||
        typeof eli.dashboard.getVisibleTools !== "function" ||
        typeof eli.dashboard.getPinState !== "function") {
      if (typeof showToast === "function") showToast("Dashboard reader API missing — kernel too old", "err");
      return;
    }
    renderCustomize({
      // Prefer getPickableTools (kernel ≥ 2026-05-16) — applies the
      // _PICKER_BLOCKLIST (e.g. compare, which only makes sense launched
      // from Legal Review's redlined-doc branch). Falls back to
      // getVisibleTools on older kernels so the picker doesn't break
      // mid-upgrade.
      getVisibleTools: function () {
        if (typeof eli.dashboard.getPickableTools === "function") {
          return eli.dashboard.getPickableTools();
        }
        return eli.dashboard.getVisibleTools();
      },
      getPinState:     function () { return eli.dashboard.getPinState(); },
      pin:             function (catId) { return eli.dashboard.pin(catId); },
      unpin:           function (catId) { return eli.dashboard.unpin(catId); },
      movePin:         function (catId, dir) { return eli.dashboard.movePin(catId, dir); },
      resetPins:       function () { return eli.dashboard.resetPins(); },
    });
  }

  // ── Help / About / Debug Console ────────────────────────────────
  // Accepts a string ("help"|"about"|"console") OR a payload object
  // {initialTab}. Kernel header click historically dispatched "console";
  // the 2026-05-13 rewrite leads with the new Help (Ask AI + feedback)
  // tab, so we silently remap that legacy string. Power-users who want
  // the event-log viewer click the Debug tab themselves.
  function openHelp(arg) {
    var initialTab = (typeof arg === "string") ? arg :
                     (arg && arg.initialTab) || "help";
    if (initialTab === "console" && !(arg && arg.initialTab)) initialTab = "help";
    if (initialTab === "contact") initialTab = "about"; // legacy alias
    renderTabbedDialog({ initialTab: initialTab });
  }

  // ── Wrongness viewer ────────────────────────────────────────────
  function openWrongness() {
    renderWrongness({});
  }

  eli.register({
    kit: {
      customize: openCustomize,
      help:      openHelp,
      wrongness: openWrongness,
    },
  });

  eli.log.event("tool", "eli_kit_initialized", {});
}

jsonTools.css:
/* tools/eli_kit/style.css
 * Three surfaces moved here from taskpane_v3.css 2026-05-11 (Batch 5E):
 *   - Customize Dashboard modal body (was kernel 1161-1320)
 *   - ._eli3_dialog_wide  (was kernel 1965 — shared by tabbed dialog +
 *     wrongness viewer)
 *   - Tabbed dialog (Help / Contact / Console) + helpers (was 2476-2679)
 *
 * The wrongness viewer uses inline styles in view.js (no class CSS yet).
 * Bundle CSS is auto-injected by the kernel at eval time and removed on
 * uninstall, so deploys without eli_kit ship without these rules.
 */

/* ─── §7.2  Customize Dashboard modal body
 *   What: rendered inside showEliDialog's `.eli-dialog-desc` slot.
 *         Two stacked sections (Installed apps / Available apps) with
 *         row-style item cards + action buttons. Reset link at the
 *         bottom.
 */
._eli3_customize_intro {
  font: 500 11.5px/1.5 'Inter', sans-serif;
  color: #475569;
  margin: 0 0 10px;
}
/* Customize dialog: kill horizontal scrollbar (items + buttons stay
 * inside the dialog width) and keep all action buttons (↑↓✕, +)
 * visible at the row edge without overflow. */
._eli3_customize_dialog { overflow-x: hidden; }
._eli3_customize_dialog ._eli3_customize_item {
  min-width: 0; /* allow text to truncate instead of forcing horizontal scroll */
}
._eli3_customize_dialog ._eli3_customize_actions {
  flex-shrink: 0; /* + and ↑↓✕ buttons never get clipped */
}
._eli3_customize_dialog ._eli3_customize_meta {
  min-width: 0;
  overflow: hidden;
}

._eli3_customize_body {
  display: flex; flex-direction: column; gap: 14px;
  text-align: left;
}
._eli3_customize_section {
  display: flex; flex-direction: column; gap: 6px;
}
._eli3_customize_subtitle {
  font: 700 10px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.5px;
  color: #1565c0;
  padding-bottom: 4px;
  border-bottom: 1px solid #e2e8f0;
}
._eli3_customize_list {
  display: flex;
  flex-direction: column;
  gap: 4px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  padding: 6px;
  /* Single scroll for the WHOLE customize panel — handled by the
     dialog body (.eli-dialog-desc). Don't add an inner overflow:auto
     here or the panel grows two nested scrollbars when both the list
     and the dialog body exceed their box. */
  overflow: visible;
}
._eli3_customize_list ._eli3_customize_catheader,
._eli3_customize_list ._eli3_customize_empty {
  width: 100%;
}
._eli3_customize_list_avail { background: transparent; border: 0; padding: 0; }
._eli3_customize_catheader {
  font: 700 9.5px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.5px;
  color: #64748b;
  padding: 8px 10px 4px;
  background: transparent;
}
/* 2026-05-17: Admin category renders inside a <details> for collapse.
   Summary keeps the same look as a plain catheader; default closed so
   admin tools don't clutter the picker for non-admin users (or admins
   who just want to scan their day-to-day tools). Native ▸/▾ marker
   replaced by our own chevron for visual consistency with the feed.   */
._eli3_customize_cat_admin > summary._eli3_customize_catheader_admin {
  list-style: none;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 6px;
  user-select: none;
  margin-top: 4px;
  padding: 9px 10px 7px;
  border-top: 1px dashed #e2e8f0;
}
._eli3_customize_cat_admin > summary._eli3_customize_catheader_admin::-webkit-details-marker {
  display: none;
}
._eli3_customize_cat_admin > summary._eli3_customize_catheader_admin::before {
  content: "▸";
  display: inline-block;
  width: 10px;
  font-size: 9px;
  color: #94a3b8;
  transition: transform 0.12s ease;
}
._eli3_customize_cat_admin[open] > summary._eli3_customize_catheader_admin::before {
  transform: rotate(90deg);
}
._eli3_customize_cat_admin > summary._eli3_customize_catheader_admin:hover {
  color: #475569;
}
._eli3_customize_admin_count {
  font-weight: 600;
  color: #94a3b8;
  letter-spacing: 0;
}
._eli3_customize_item {
  display: flex; align-items: center; gap: 10px;
  padding: 8px 10px;
  background: #fff;
  border: 1px solid #e2e8f0;
  margin: 2px 0;
}
._eli3_customize_item_pinned { background: #fff; }
._eli3_customize_item_avail {
  cursor: pointer;
  transition: background 0.12s, border-color 0.12s;
}
._eli3_customize_item_avail:hover {
  background: #eff6ff;
  border-color: #93c5fd;
}
._eli3_customize_item_core {
  border-color: rgba(201, 162, 39, 0.55);
  background: rgba(254, 249, 219, 0.6);
}
._eli3_customize_icon {
  flex: 0 0 auto;
  width: 26px; height: 26px;
  display: inline-flex; align-items: center; justify-content: center;
  font-size: 16px;
}
._eli3_customize_meta {
  flex: 1 1 auto;
  min-width: 0;
}
._eli3_customize_name {
  font: 700 12px/1.2 'Inter', sans-serif;
  color: #0f172a;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
._eli3_customize_desc {
  font: 500 10.5px/1.3 'Inter', sans-serif;
  color: #64748b;
  margin-top: 1px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
._eli3_customize_corebadge {
  display: inline-block;
  margin-left: 6px;
  padding: 1px 5px;
  font: 700 8.5px/1 'Inter', sans-serif;
  letter-spacing: 0.5px;
  background: rgba(201, 162, 39, 0.18);
  color: #92400e;
  border: 1px solid rgba(201, 162, 39, 0.5);
  vertical-align: middle;
}
._eli3_customize_actions {
  flex: 0 0 auto;
  display: flex; align-items: center; gap: 4px;
}
._eli3_customize_btn {
  width: 24px; height: 24px;
  display: inline-flex; align-items: center; justify-content: center;
  font: 700 12px/1 'Inter', sans-serif;
  background: linear-gradient(to bottom, #f7f9fa 0%, #dce3e8 100%);
  color: #475569;
  border: 1px solid #cbd5e1;
  cursor: pointer;
  transition: all 0.12s;
  user-select: none;
}
._eli3_customize_btn:hover:not(:disabled) {
  background: linear-gradient(to bottom, #fff 0%, #e3f2fd 100%);
  color: #1565c0;
  border-color: #90caf9;
}
._eli3_customize_btn_remove:hover {
  background: #fef2f2 !important;
  color: #b91c1c !important;
  border-color: #fca5a5 !important;
}
._eli3_customize_btn_add {
  background: linear-gradient(135deg, #1565c0 0%, #0d47a1 100%);
  color: #fff;
  border-color: #0d47a1;
  font-size: 14px;
}
._eli3_customize_btn_add:hover {
  background: linear-gradient(135deg, #1d4ed8 0%, #1565c0 100%) !important;
  color: #fff !important;
  border-color: #0d47a1 !important;
}
._eli3_customize_locked {
  font: 700 9px/1 'Inter', sans-serif;
  letter-spacing: 1px;
  color: rgba(180, 83, 9, 0.8);
  padding: 0 8px;
}
._eli3_customize_empty {
  padding: 12px;
  font: 500 11px/1.5 'Inter', sans-serif;
  color: #94a3b8;
  font-style: italic;
  text-align: center;
}
._eli3_customize_resetrow {
  display: flex; justify-content: flex-end;
  padding-top: 8px;
  border-top: 1px solid #e2e8f0;
}
._eli3_customize_reset {
  background: none; border: 0;
  font: 700 10px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.5px;
  color: #94a3b8;
  cursor: pointer;
  padding: 4px 8px;
  transition: color 0.12s;
}
._eli3_customize_reset:hover { color: #b91c1c; text-decoration: underline; }

/* Dark mode — user-requested 2026-05-11. Customize lives in the dashboard
 * chrome (the + button anchors here), so it follows the same theme as the
 * unpinned menu rather than the dialog default. Palette mirrors v2's
 * openCatalogModal dark variant. Scoped to the dialog wrapper so it
 * doesn't leak into other dialogs that happen to embed customize-style
 * rows. */
body:not(.light-mode) ._eli3_customize_dialog {
  background: #0f172a;
  color: #f1f5f9;
}
body:not(.light-mode) ._eli3_customize_dialog .eli-dialog-desc { color: #f1f5f9; }
body:not(.light-mode) ._eli3_customize_dialog .eli-dialog-title { color: #f1f5f9; }
body:not(.light-mode) ._eli3_customize_dialog .eli-dialog-close { color: #94a3b8; }
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_intro { color: #94a3b8; }
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_subtitle {
  color: #f2d866;
  border-bottom-color: #334155;
}
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_list {
  background: #1e293b;
  border-color: #334155;
}
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_list_avail {
  background: transparent;
  border: 0;
}
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_catheader { color: #94a3b8; }
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_item,
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_item_pinned {
  background: #1e293b;
  border-color: #334155;
}
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_item_avail:hover {
  background: #334155;
  border-color: #475569;
}
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_item_core {
  border-color: rgba(201,162,39,0.55);
  background: rgba(201,162,39,0.10);
}
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_name { color: #f1f5f9; }
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_desc { color: #94a3b8; }
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_corebadge {
  background: rgba(201,162,39,0.20);
  color: #f2d866;
  border-color: rgba(201,162,39,0.55);
}
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_btn {
  background: linear-gradient(to bottom, #334155 0%, #1e293b 100%);
  color: #cbd5e1;
  border-color: #475569;
}
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_btn:hover:not(:disabled) {
  background: linear-gradient(to bottom, #475569 0%, #334155 100%);
  color: #f2d866;
  border-color: #64748b;
}
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_btn_remove:hover {
  background: #7f1d1d !important;
  color: #fecaca !important;
  border-color: #b91c1c !important;
}
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_locked { color: #f2d866; }
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_empty { color: #64748b; }
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_resetrow {
  border-top-color: #334155;
}
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_reset { color: #64748b; }
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_reset:hover { color: #fecaca; }

/* ── Shared dialog widening — used by both the tabbed dialog and the wrongness viewer ── */
._eli3_dialog_wide { width: 620px; max-width: 94vw; }

/* ─── §15  Tabbed dialog (ELI logo click → Help/Contact/Console)
 *   What: tab bar at top of the dialog body + active-tab underline +
 *     individual tab panels (help, contact, console).
 *   Who emits: kernel's _tabbedDialog() + _buildHelpTab / _buildContactTab
 *     / _buildConsoleTab.
 *   Override: rare. Tool authors don't customize this dialog. */
/* 2026-05-13 premium: ELI AI dialog tabs — dark navy bar with gold
   active-tab accent, larger touch target, smoother hover.

   2026-05-13 follow-up fix: dropped the `margin-top: -16px` that pulled
   the tab bar UP into the dialog header area, leaving the "ELI AI"
   title visually jammed against the navy tab strip with no breathing
   room. Header now has its own bottom border + 14px gap; the tab bar
   sits cleanly beneath it. Side bleed (-20px each) is retained so the
   navy strip still spans the full dialog width. */
/* 2026-05-16 — tab bar reworked to avoid side-bleed clipping by the
   outer dialog's overflow:hidden (needed for single-scrollbar). Bar
   now sits as a styled card within the dialog body — clean rounded
   corners, premium navy gradient, gold underline accent. flex: 0 0
   auto so the flex chain never shrinks it. */
._eli3_tabs {
  display: flex;
  gap: 2px;
  background: linear-gradient(135deg, #0d1b2a 0%, #1b263b 60%, #243b5e 100%);
  padding: 8px 8px 0;
  margin: 0 0 18px;
  border-radius: 8px 8px 0 0;
  border-bottom: 3px solid #c9a227;
  position: relative;
  box-shadow:
    0 4px 12px rgba(13, 27, 42, 0.25),
    inset 0 1px 0 rgba(255, 255, 255, 0.06);
  flex: 0 0 auto;
}
._eli3_tabs::before {
  /* Subtle gold sheen along the top edge — adds depth. */
  content: "";
  position: absolute;
  top: 0; left: 8px; right: 8px;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(242, 216, 102, 0.35) 50%, transparent);
  pointer-events: none;
}
._eli3_tabs::after {
  /* Gold accent line just under the bottom border. */
  content: "";
  position: absolute;
  left: 14%; right: 14%; bottom: -3px;
  height: 3px;
  background: linear-gradient(90deg, transparent, rgba(242, 216, 102, 0.7) 50%, transparent);
  pointer-events: none;
}
._eli3_tab {
  padding: 11px 18px 9px;
  font: 800 10.5px/1.2 'Inter', sans-serif;
  letter-spacing: 0.9px;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.6);
  cursor: pointer;
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
  background: transparent;
  border-radius: 6px 6px 0 0;
  transition: color .15s, background .15s, border-color .15s, transform .12s;
  user-select: none;
}
._eli3_tab:hover {
  color: #fff;
  background: rgba(255, 255, 255, 0.06);
  transform: translateY(-1px);
}
._eli3_tab_active {
  color: #f2d866;
  background: linear-gradient(180deg, rgba(201, 162, 39, 0.16) 0%, rgba(201, 162, 39, 0.04) 100%);
  border-bottom-color: transparent;
  position: relative;
  text-shadow: 0 0 12px rgba(242, 216, 102, 0.3);
}
._eli3_tab_active::after {
  content: "";
  position: absolute;
  left: 10px; right: 10px; bottom: -3px;
  height: 3px;
  background: linear-gradient(90deg, #c9a227, #f2d866 50%, #c9a227);
  z-index: 1;
  border-radius: 2px 2px 0 0;
}
._eli3_tabpanel {
  font-size: 12px;
  line-height: 1.5;
  color: var(--text-on-light);
  min-height: 420px;
}
/* 2026-05-16 rewrite — outer dialog now caps + locks (overflow:hidden
   on the dialog itself, see _eli3_dialog_tabbed_v2 below), so this
   inner pane is THE sole scroll surface. Eliminates the double-
   scrollbar that previously appeared when the dialog AND the tabpanel
   both overflowed. Height bumped 460→520 for more visible content. */
._eli3_tabpanel_fixed {
  height: 520px;
  overflow-y: auto;
  padding-right: 8px;
  /* Custom scrollbar styling for a more premium feel. */
  scrollbar-width: thin;
  scrollbar-color: #c9a227 transparent;
}
._eli3_tabpanel_fixed::-webkit-scrollbar { width: 8px; }
._eli3_tabpanel_fixed::-webkit-scrollbar-track { background: transparent; }
._eli3_tabpanel_fixed::-webkit-scrollbar-thumb {
  background: linear-gradient(180deg, #c9a227 0%, #a8841d 100%);
  border-radius: 4px;
  border: 2px solid transparent;
  background-clip: padding-box;
}
._eli3_tabpanel_fixed::-webkit-scrollbar-thumb:hover {
  background: linear-gradient(180deg, #d4af37 0%, #b8932a 100%);
  background-clip: padding-box;
}

/* Help tab */
._eli3_help_section {
  margin-bottom: var(--space-4);
  padding-bottom: var(--space-3);
  border-bottom: 1px solid #f1f5f9;
}
._eli3_help_section:last-child { border-bottom: none; padding-bottom: 0; }
._eli3_help_section h4 {
  font: var(--weight-extrabold) var(--font-md)/1.3 var(--font-family);
  letter-spacing: 0.6px;
  text-transform: uppercase;
  color: var(--color-blue);
  margin: 0 0 var(--space-2);
}
._eli3_help_section p {
  font-size: 12px;
  line-height: 1.55;
  color: var(--text-on-light);
  margin: 0 0 var(--space-2);
}
._eli3_help_section ul {
  margin: var(--space-1) 0 0 var(--space-3);
  padding: 0;
}
._eli3_help_section li {
  margin-bottom: var(--space-1);
  font-size: 12px;
  line-height: 1.55;
  color: var(--text-on-light);
}
._eli3_help_section code {
  font-family: var(--font-mono);
  font-size: var(--font-md);
  background: #f1f5f9;
  border: 1px solid #e2e8f0;
  padding: 1px var(--space-1);
  color: var(--text-on-light);
}

/* Help → Recovery actions block */
#_eli3_help_recovery_btns {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: var(--space-2);
}
#_eli3_help_recovery_btns .btn-action {
  flex: 0 0 auto;
  text-align: center;
}

/* Contact tab — kv table */
._eli3_kv_row {
  display: grid;
  grid-template-columns: 110px 1fr;
  gap: var(--space-3);
  padding: 6px 0;
  border-bottom: 1px solid #f1f5f9;
  font-size: 12px;
}
._eli3_kv_row:last-child { border-bottom: none; }
._eli3_kv_label {
  font-weight: var(--weight-bold);
  color: var(--text-status-footer);
}
._eli3_kv_value {
  flex: 1;
  font-family: var(--font-mono);
  word-break: break-all;
  color: var(--text-on-light);
}

/* Console tab — toolbar + log list */
._eli3_console_toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-1);
  align-items: center;
  padding: 6px var(--space-2);
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  margin-bottom: 6px;
}
._eli3_filter_btn {
  padding: 4px 10px;
  font: var(--weight-bold) var(--font-xs)/1 var(--font-family);
  letter-spacing: 0.3px;
  text-transform: uppercase;
  background: linear-gradient(to bottom, #f7f9fa 0%, #dce3e8 100%);
  border: 1px solid #b0bec5;
  color: var(--text-status-footer);
  cursor: pointer;
  transition: all .15s ease;
}
._eli3_filter_btn:hover {
  background: linear-gradient(to bottom, #ffffff 0%, #e3f2fd 100%);
  border-color: #90caf9;
  color: var(--color-blue);
}
._eli3_filter_btn_active {
  background: linear-gradient(135deg, var(--color-blue) 0%, var(--color-blue-deep) 100%);
  color: #fff;
  border-color: var(--color-blue-deep);
}
._eli3_filter_btn_active:hover {
  background: linear-gradient(135deg, #1976d2 0%, var(--color-blue) 100%);
  color: #fff;
  border-color: var(--color-blue);
}
/* Copy + Clear buttons in the console toolbar — same platinum treatment */
._eli3_console_toolbar button:not(._eli3_filter_btn) {
  padding: 4px 10px;
  font: var(--weight-bold) var(--font-xs)/1 var(--font-family);
  letter-spacing: 0.3px;
  text-transform: uppercase;
  background: linear-gradient(to bottom, #f7f9fa 0%, #dce3e8 100%);
  border: 1px solid #b0bec5;
  color: var(--text-status-footer);
  cursor: pointer;
  transition: all .15s ease;
}
._eli3_console_toolbar button:not(._eli3_filter_btn):hover {
  background: linear-gradient(to bottom, #ffffff 0%, #e3f2fd 100%);
  border-color: #90caf9;
  color: var(--color-blue);
}
._eli3_console_meta {
  margin-left: auto;
  font: var(--weight-semibold) var(--font-sm)/1 var(--font-family);
  color: var(--text-dim);
}
._eli3_log_list {
  max-height: 360px;
  overflow-y: auto;
  border: 1px solid #e2e8f0;
}
._eli3_log_row {
  display: flex;
  gap: 6px;
  padding: var(--space-1) var(--space-2);
  border-bottom: 1px solid #f1f5f9;
  font: var(--font-md)/1.4 var(--font-mono);
  flex-wrap: wrap;
}
._eli3_log_time { color: var(--text-dim); flex-shrink: 0; }
._eli3_log_chan {
  color: var(--color-blue);
  font-weight: var(--weight-bold);
  flex-shrink: 0;
  min-width: 50px;
}
._eli3_log_msg { flex: 1; color: var(--text-on-light); }
._eli3_log_payload {
  width: 100%;
  margin-top: 2px;
  padding-left: 56px;
  font-size: var(--font-sm);
  color: var(--text-status-footer);
  word-break: break-all;
}
._eli3_log_empty {
  padding: var(--space-3);
  text-align: center;
  font-style: italic;
  color: var(--text-dim);
  font-size: var(--font-md);
}

/* ─── 2026-05-13 rewrite — Help / About surfaces ──────────────────
 *   Premium card treatment shared by Ask AI, Submit Feedback, and
 *   Announcements blocks. About uses a hero + stat grid (no buttons).
 */
/* 2026-05-13 follow-up: premium dialog header for the ELI AI tabbed
   surface. Larger serif title, gold-haloed icon, soft hairline divider,
   and clear 16px gap before the tab bar. Replaces the original cramped
   header (12px title, no separator) where the tab bar sat almost flush
   against the title text. */
/* 2026-05-16 final: restored the simple header above the tab strip.
   Header has ⚡ icon + "ELI AI" title; below it sits the premium navy
   tab strip; below that, the scrolling tab panel. Outer dialog locks
   to viewport height so only the tab panel scrolls (eliminates the
   double scrollbar). */
._eli3_dialog_tabbed_v2.eli-dialog {
  padding: 12px 20px 16px;
  max-height: 90vh;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}
._eli3_dialog_tabbed_v2 .eli-dialog-header {
  flex: 0 0 auto;
  margin-bottom: 12px;
}
._eli3_dialog_tabbed_v2 .eli-dialog-desc {
  flex: 1 1 auto;
  min-height: 0;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  margin: 0;
}
._eli3_dialog_tabbed_v2 #_eli3_tabbed_body {
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
._eli3_dialog_tabbed_v2 ._eli3_tabpanel {
  flex: 1 1 auto;
  min-height: 0;
}
._eli3_dialog_tabbed_v2 .eli-dialog-actions {
  flex: 0 0 auto;
}

/* 2026-05-16 premium pass: each card now has a richer treatment —
   subtle gradient background, soft elevation, smooth lift on hover,
   refined accent stripe per section. Bug + Feedback gets the gold
   stripe; Help cards alternate blue/purple. */
._eli3_help_card {
  background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
  border: 1px solid #e2e8f0;
  border-left: 4px solid #cbd5e1;
  border-radius: 8px;
  padding: 16px 18px 16px 16px;
  margin-bottom: 14px;
  box-shadow:
    0 1px 2px rgba(15, 23, 42, 0.04),
    0 2px 6px rgba(15, 23, 42, 0.04);
  transition: box-shadow 0.18s ease, transform 0.12s ease, border-color 0.18s ease;
}
._eli3_help_card:hover {
  box-shadow:
    0 2px 4px rgba(15, 23, 42, 0.06),
    0 8px 18px rgba(15, 23, 42, 0.08);
  transform: translateY(-1px);
}
._eli3_help_card:last-child { margin-bottom: 0; }

/* Color-coded accents per section. */
._eli3_help_card:nth-of-type(1) { border-left-color: #1565c0; }   /* Ask AI — blue */
._eli3_help_card:nth-of-type(2) { border-left-color: #7c3aed; }   /* Second card (announcements when on Help) — purple */
._eli3_help_card._eli3_help_card_announce { border-left-color: #7c3aed; }
/* Bug tab — single card, gold accent. */
._eli3_help_card._eli3_help_card_bug { border-left-color: #c9a227; }

._eli3_help_card_head {
  display: flex;
  gap: 11px;
  align-items: flex-start;
  margin-bottom: 12px;
}
._eli3_help_card_icon {
  flex: 0 0 auto;
  width: 32px; height: 32px;
  display: inline-flex; align-items: center; justify-content: center;
  font-size: 18px;
  background: linear-gradient(135deg, #f8fafc 0%, #e2e8f0 100%);
  border: 1px solid #cbd5e1;
  border-radius: 50%;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.6);
}
._eli3_help_card:nth-of-type(1) ._eli3_help_card_icon {
  background: linear-gradient(135deg, #dbeafe 0%, #bfdbfe 100%);
  border-color: #93c5fd;
}
._eli3_help_card:nth-of-type(2) ._eli3_help_card_icon {
  background: linear-gradient(135deg, #fef3c7 0%, #fde68a 100%);
  border-color: #fcd34d;
}
._eli3_help_card._eli3_help_card_announce ._eli3_help_card_icon {
  background: linear-gradient(135deg, #ede9fe 0%, #ddd6fe 100%);
  border-color: #c4b5fd;
}
._eli3_help_card_titles { flex: 1 1 auto; min-width: 0; }
._eli3_help_card_title {
  font: 800 13.5px/1.2 'Book Antiqua', Georgia, serif;
  color: #0f172a;
  letter-spacing: 0.2px;
}
._eli3_help_card_sub {
  font: 500 11px/1.5 'Inter', sans-serif;
  color: #64748b;
  margin-top: 3px;
}

/* ── Ask AI ── */
._eli3_help_ask_input {
  width: 100%;
  padding: 8px 10px;
  font: 500 12px/1.45 'Inter', sans-serif;
  color: #0f172a;
  background: #f8fafc;
  border: 1px solid #cbd5e1;
  border-radius: 6px;
  outline: none;
  resize: vertical;
  box-sizing: border-box;
  transition: border-color .12s, background .12s;
}
._eli3_help_ask_input:focus {
  border-color: #1565c0;
  background: #fff;
}
._eli3_help_ask_row {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 8px;
}
._eli3_help_ask_hint {
  font: 500 10.5px/1 'Inter', sans-serif;
  color: #94a3b8;
}
._eli3_help_ask_answer {
  margin-top: 12px;
  padding: 10px 12px;
  background: linear-gradient(135deg, #f8fafc 0%, #f1f5f9 100%);
  border: 1px solid #e2e8f0;
  border-radius: 6px;
}
._eli3_help_ask_answer_text {
  font: 500 12px/1.55 'Inter', sans-serif;
  color: #0f172a;
}
._eli3_help_ask_answer_text p { margin: 0 0 8px; }
._eli3_help_ask_answer_text p:last-child { margin-bottom: 0; }
._eli3_help_ask_pending {
  font: 500 11.5px/1.5 'Inter', sans-serif;
  color: #64748b;
}
._eli3_help_ask_err {
  font: 600 11.5px/1.5 'Inter', sans-serif;
  color: #b91c1c;
}

/* ==================================================================
   Ask ELI — redesigned 2026-05-23 (revised: panel-class removed, hero
   shrunk so title isn't cut off, wrap sizes naturally inside parent
   instead of forcing height:100%)
   ================================================================== */
/* 2026-05-23: block layout, NOT flex. First-open of the dialog had a
   layout race where the flex children sized to 0 because the parent
   tabbed-body hadn't finished mounting; flipping to plain block sidesteps
   the issue entirely (display:block paints content at its natural size
   regardless of parent's layout state). Spacing via margin instead of gap. */
._eli3_ask_wrap {
  display: block;
}
._eli3_ask_wrap > * {
  margin-bottom: 10px;
}
._eli3_ask_wrap > *:last-child {
  margin-bottom: 0;
}

/* ── Hero (compact) ── */
._eli3_ask_hero {
  position: relative;
  background:
    radial-gradient(circle at 80% 20%, rgba(255, 255, 255, 0.12), transparent 50%),
    linear-gradient(135deg, #0f172a 0%, #1e3a8a 55%, #1565c0 100%);
  color: #fff;
  padding: 14px 18px 12px;
  border-radius: 10px;
  overflow: hidden;
  box-shadow: 0 3px 10px rgba(15, 23, 42, 0.18);
}
._eli3_ask_hero_starfield {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.55;
}
._eli3_ask_star {
  position: absolute;
  color: #fde68a;
  font-size: 12px;
  animation: _eli3_ask_twinkle 3.4s ease-in-out infinite;
}
._eli3_ask_star_1 { top: 14%;  left: 12%; font-size: 8px;  animation-delay: 0s; }
._eli3_ask_star_2 { top: 30%;  left: 78%; font-size: 11px; animation-delay: 0.6s; }
._eli3_ask_star_3 { top: 65%;  left: 22%; font-size: 9px;  animation-delay: 1.1s; }
._eli3_ask_star_4 { top: 22%;  left: 52%; font-size: 14px; animation-delay: 1.7s; }
._eli3_ask_star_5 { top: 78%;  left: 88%; font-size: 10px; animation-delay: 2.2s; }
@keyframes _eli3_ask_twinkle {
  0%, 100% { opacity: 0.3; transform: scale(1); }
  50%      { opacity: 1;   transform: scale(1.25); }
}
._eli3_ask_hero_body {
  position: relative;
  display: flex;
  gap: 16px;
  align-items: center;
}
._eli3_ask_hero_icon {
  flex: 0 0 auto;
  width: 40px; height: 40px;
  display: inline-flex; align-items: center; justify-content: center;
  font-size: 22px;
  background: linear-gradient(135deg, #fef3c7 0%, #fde68a 100%);
  color: #92400e;
  border-radius: 50%;
  box-shadow:
    0 2px 5px rgba(0,0,0,0.25),
    inset 0 1px 0 rgba(255,255,255,0.6);
}

/* 2026-05-26: ELI mascot in the hero header slot. Replaces the
   _eli3_ask_hero_icon sparkle. Sized large to anchor the hero — Eli
   IS the hero element here, not an icon next to one. Three layers
   give him pop against the navy background:
     1. _eli3_kit_mascot_glow — pulsing radial gold/blue halo behind
     2. SVG's own pale-blue ambient aura circle (built into the svg)
     3. blue-tinted drop-shadow for separation + life
   Animations scoped under `_eli3_kit_mascot_*` keep eli_kit self-
   contained (ask_eli has its own `_eli3_mascot_*` copy). */
._eli3_kit_mascot_wrap {
  position: relative;
  flex: 0 0 auto;
  width: 110px;
  height: 132px;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  filter:
    drop-shadow(0 4px 8px rgba(13, 71, 161, 0.45))
    drop-shadow(0 2px 3px rgba(0, 0, 0, 0.5));
}
._eli3_kit_mascot_glow {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background:
    radial-gradient(circle at 50% 45%,
      rgba(253, 224, 71, 0.32) 0%,
      rgba(147, 197, 253, 0.22) 35%,
      transparent 70%);
  animation: _eli3_kit_mascot_glow_pulse 3.2s ease-in-out infinite;
  pointer-events: none;
  z-index: 0;
}
@keyframes _eli3_kit_mascot_glow_pulse {
  0%, 100% { opacity: 0.7;  transform: scale(1); }
  50%      { opacity: 1;    transform: scale(1.08); }
}
._eli3_kit_mascot_svg {
  position: relative;
  z-index: 1;
  display: block;
  animation: _eli3_kit_mascot_breathe_body 1.8s ease-in-out infinite alternate;
  transform-origin: center bottom;
}
._eli3_kit_mascot_svg ._eli3_kit_mascot_head {
  animation: _eli3_kit_mascot_breathe_head 1.8s ease-in-out infinite alternate;
  transform-origin: 60px 85px;
}
._eli3_kit_mascot_svg ._eli3_kit_mascot_eyes  { animation: _eli3_kit_mascot_blink     4s infinite; }
._eli3_kit_mascot_svg ._eli3_kit_mascot_eyelids { animation: _eli3_kit_mascot_blink_lid 4s infinite; }
._eli3_kit_mascot_svg ._eli3_kit_mascot_eyeball {
  animation: _eli3_kit_mascot_look 6s infinite;
  transition: transform 0.25s ease;
}
@keyframes _eli3_kit_mascot_breathe_body {
  0%   { transform: scale(1); }
  100% { transform: scale(1.02); }
}
@keyframes _eli3_kit_mascot_breathe_head {
  0%   { transform: translateY(0); }
  100% { transform: translateY(-2px); }
}
@keyframes _eli3_kit_mascot_blink {
  0%, 90%, 100% { opacity: 1; }
  93%, 97%      { opacity: 0; }
}
@keyframes _eli3_kit_mascot_blink_lid {
  0%, 90%, 100% { opacity: 0; }
  93%, 97%      { opacity: 1; }
}
@keyframes _eli3_kit_mascot_look {
  0%, 50%, 100% { transform: translate(0, 0); }
  15%, 25%      { transform: translate(-2px, 0.5px); }
  65%, 75%      { transform: translate(2px, -0.5px); }
}
._eli3_ask_hero_text { flex: 1 1 auto; min-width: 0; }
._eli3_ask_hero_title {
  font: 800 16px/1.15 'Book Antiqua', Georgia, serif;
  letter-spacing: 0.3px;
}
._eli3_ask_hero_sub {
  font: 500 11.5px/1.45 'Inter', sans-serif;
  color: #cbd5e1;
  margin-top: 2px;
}
._eli3_ask_hero_meta {
  position: relative;
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px solid rgba(255, 255, 255, 0.12);
  font: 500 10.5px/1.3 'Inter', sans-serif;
  color: #93c5fd;
  letter-spacing: 0.3px;
}
._eli3_ask_meta_dot {
  color: #4ade80;
  font-size: 8px;
  margin-right: 4px;
  vertical-align: middle;
}
._eli3_ask_hero_meta b { color: #fff; font-weight: 700; }

/* ── Suggestion chips ── */
._eli3_ask_chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
._eli3_ask_chip {
  font: 500 11.5px/1 'Inter', sans-serif;
  color: #1e3a8a;
  background: linear-gradient(180deg, #ffffff 0%, #f1f5f9 100%);
  border: 1px solid #cbd5e1;
  border-radius: 999px;
  padding: 7px 12px 7px 10px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  transition: transform 0.1s ease, box-shadow 0.15s ease, border-color 0.15s ease, background 0.15s ease;
}
._eli3_ask_chip:hover {
  background: linear-gradient(180deg, #eff6ff 0%, #dbeafe 100%);
  border-color: #1565c0;
  box-shadow: 0 2px 8px rgba(21, 101, 192, 0.18);
  transform: translateY(-1px);
}
._eli3_ask_chip_icon {
  color: #1565c0;
  font-weight: 800;
}

/* ── Input ── */
._eli3_ask_inputwrap {
  background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
  border: 1px solid #cbd5e1;
  border-radius: 10px;
  padding: 12px 12px 10px;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}
._eli3_ask_inputwrap:focus-within {
  border-color: #1565c0;
  box-shadow: 0 0 0 3px rgba(21, 101, 192, 0.15);
}
._eli3_ask_input {
  width: 100%;
  font: 500 13.5px/1.5 'Inter', sans-serif;
  color: #0f172a;
  background: transparent;
  border: none;
  outline: none;
  resize: vertical;
  min-height: 60px;
  box-sizing: border-box;
}
._eli3_ask_input::placeholder { color: #94a3b8; font-style: italic; }
._eli3_ask_inputfoot {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 10px;
}
._eli3_ask_hint {
  font: 500 10.5px/1 'Inter', sans-serif;
  color: #94a3b8;
}
._eli3_ask_btn {
  font: 700 13px/1 'Inter', sans-serif;
  color: #fff;
  background: linear-gradient(135deg, #1565c0 0%, #0d47a1 100%);
  border: none;
  border-radius: 8px;
  padding: 10px 18px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  box-shadow: 0 2px 6px rgba(21, 101, 192, 0.35);
  transition: transform 0.1s ease, box-shadow 0.15s ease, filter 0.15s ease;
}
._eli3_ask_btn:hover:not(:disabled) {
  filter: brightness(1.07);
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(21, 101, 192, 0.45);
}
._eli3_ask_btn:disabled { opacity: 0.7; cursor: progress; }
._eli3_ask_btn_icon { font-size: 14px; }
._eli3_ask_btn_spin { animation: _eli3_ask_spin 1.4s linear infinite; }
@keyframes _eli3_ask_spin {
  from { transform: rotate(0deg); }
  to   { transform: rotate(360deg); }
}

/* ── Answer area (fills remaining space) ── */
._eli3_ask_answerwrap {
  min-height: 140px;
  display: flex;
}
._eli3_ask_answer {
  flex: 1 1 auto;
  border-radius: 12px;
  padding: 18px 20px;
  overflow-y: auto;
}
._eli3_ask_answer_empty {
  background:
    radial-gradient(circle at 30% 20%, rgba(255, 224, 102, 0.08), transparent 60%),
    radial-gradient(circle at 70% 80%, rgba(21, 101, 192, 0.06), transparent 60%),
    #f8fafc;
  border: 1px dashed #cbd5e1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  gap: 6px;
}
._eli3_ask_empty_emoji {
  font-size: 38px;
  margin-bottom: 4px;
  filter: drop-shadow(0 2px 6px rgba(15, 23, 42, 0.1));
}
._eli3_ask_empty_msg {
  font: 700 14px/1.3 'Book Antiqua', Georgia, serif;
  color: #0f172a;
}
._eli3_ask_empty_hint {
  font: 500 12px/1.5 'Inter', sans-serif;
  color: #64748b;
  max-width: 360px;
}
._eli3_ask_answer_ok {
  background:
    linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
  border: 1px solid #e2e8f0;
  box-shadow: 0 2px 8px rgba(15, 23, 42, 0.06);
}
._eli3_ask_answer_text {
  font: 500 13px/1.65 'Inter', sans-serif;
  color: #0f172a;
}
._eli3_ask_answer_text p { margin: 0 0 10px; }
._eli3_ask_answer_text p:last-child { margin-bottom: 0; }
._eli3_ask_answer_text code {
  background: #eff6ff;
  color: #1e3a8a;
  padding: 1px 6px;
  border-radius: 3px;
  font: 12px/1.4 'Monaco', monospace;
}
._eli3_ask_answer_text strong { color: #1e3a8a; }

/* Pending dots */
._eli3_ask_answer_pending {
  background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
  border: 1px solid #e2e8f0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  gap: 10px;
}
._eli3_ask_pending_dots {
  display: inline-flex;
  gap: 6px;
}
._eli3_ask_pending_dots span {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #1565c0;
  display: inline-block;
  animation: _eli3_ask_bounce 1.2s infinite ease-in-out;
}
._eli3_ask_pending_dots span:nth-child(2) { animation-delay: 0.15s; }
._eli3_ask_pending_dots span:nth-child(3) { animation-delay: 0.3s; }
@keyframes _eli3_ask_bounce {
  0%, 60%, 100% { transform: translateY(0); opacity: 0.4; }
  30%           { transform: translateY(-6px); opacity: 1; }
}
._eli3_ask_pending_msg {
  font: 500 12.5px/1.4 'Inter', sans-serif;
  color: #475569;
}

/* Error state */
._eli3_ask_answer_err {
  background: #fef2f2;
  border: 1px solid #fecaca;
  border-left: 4px solid #b91c1c;
}
._eli3_ask_err {
  display: flex;
  gap: 12px;
  align-items: flex-start;
}
._eli3_ask_err_icon {
  font-size: 24px;
  flex: 0 0 auto;
  color: #b91c1c;
}
._eli3_ask_err_msg {
  flex: 1;
  font: 500 12.5px/1.5 'Inter', sans-serif;
  color: #7f1d1d;
}
._eli3_ask_err_msg b { color: #991b1b; }

/* ── Shared buttons inside Help cards ── */
._eli3_help_btn_primary {
  padding: 7px 16px;
  font: 700 11px/1 'Inter', sans-serif;
  letter-spacing: 0.4px;
  text-transform: uppercase;
  background: linear-gradient(135deg, #1565c0 0%, #0d47a1 100%);
  color: #fff;
  border: 1px solid #0d47a1;
  border-radius: 6px;
  cursor: pointer;
  transition: all .12s;
}
._eli3_help_btn_primary:hover:not(:disabled) {
  background: linear-gradient(135deg, #1d4ed8 0%, #1565c0 100%);
}
._eli3_help_btn_primary:disabled { opacity: 0.55; cursor: progress; }
._eli3_help_btn_ghost {
  padding: 7px 14px;
  font: 700 11px/1 'Inter', sans-serif;
  letter-spacing: 0.4px;
  text-transform: uppercase;
  background: linear-gradient(to bottom, #f7f9fa 0%, #dce3e8 100%);
  color: #475569;
  border: 1px solid #b0bec5;
  border-radius: 6px;
  cursor: pointer;
  transition: all .12s;
}
._eli3_help_btn_ghost:hover:not(:disabled) {
  background: linear-gradient(to bottom, #fff 0%, #e3f2fd 100%);
  color: #1565c0;
  border-color: #90caf9;
}

/* ── Submit feedback ── */
._eli3_help_typerow {
  display: flex;
  gap: 8px;
  margin-bottom: 8px;
}
._eli3_help_typetile {
  flex: 1 1 0;
  display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  padding: 8px 10px;
  background: #f8fafc;
  border: 1px solid #cbd5e1;
  border-radius: 6px;
  font: 700 11.5px/1 'Inter', sans-serif;
  color: #475569;
  cursor: pointer;
  transition: all .12s;
}
._eli3_help_typetile input { display: none; }
._eli3_help_typetile:hover { border-color: #93c5fd; color: #1565c0; }
._eli3_help_typetile_active {
  background: linear-gradient(135deg, #eff6ff 0%, #dbeafe 100%);
  border-color: #1565c0;
  color: #0d47a1;
  box-shadow: inset 0 0 0 1px #1565c0;
}
._eli3_help_fb_title,
._eli3_help_fb_body {
  width: 100%;
  padding: 8px 10px;
  margin-bottom: 8px;
  font: 500 12px/1.45 'Inter', sans-serif;
  color: #0f172a;
  background: #f8fafc;
  border: 1px solid #cbd5e1;
  border-radius: 6px;
  outline: none;
  box-sizing: border-box;
  transition: border-color .12s, background .12s;
}
._eli3_help_fb_body { resize: vertical; min-height: 60px; }
._eli3_help_fb_title:focus,
._eli3_help_fb_body:focus {
  border-color: #1565c0;
  background: #fff;
}
._eli3_help_fb_actions {
  display: flex;
  gap: 8px;
  align-items: center;
}
._eli3_help_fb_status {
  margin-top: 8px;
  font: 600 11px/1.4 'Inter', sans-serif;
  min-height: 16px;
}
._eli3_help_fb_status_ok       { color: #15803d; }
._eli3_help_fb_status_warn     { color: #b45309; }
._eli3_help_fb_status_err      { color: #b91c1c; }
._eli3_help_fb_status_pending  { color: #64748b; font-style: italic; }

/* ── Announcements list ── */
._eli3_help_announce_list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
._eli3_help_announce_empty {
  padding: 16px;
  text-align: center;
  font: 500 11px/1.4 'Inter', sans-serif;
  color: #94a3b8;
  font-style: italic;
}
._eli3_help_announce_row {
  display: flex;
  gap: 10px;
  padding: 9px 11px;
  background: #fafbfc;
  border: 1px solid #e2e8f0;
  border-radius: 6px;
  cursor: pointer;
  transition: all .12s;
}
._eli3_help_announce_row:hover {
  border-color: #93c5fd;
  background: #f0f9ff;
}
._eli3_help_announce_new {
  border-left: 3px solid #1565c0;
  background: linear-gradient(135deg, #eff6ff 0%, #f8fafc 100%);
}
._eli3_help_announce_icon {
  flex: 0 0 auto;
  width: 24px; height: 24px;
  display: inline-flex; align-items: center; justify-content: center;
  font-size: 14px;
}
._eli3_help_announce_meta { flex: 1 1 auto; min-width: 0; }
._eli3_help_announce_title {
  font: 700 12px/1.3 'Inter', sans-serif;
  color: #0f172a;
}
._eli3_help_announce_newbadge {
  display: inline-block;
  margin-left: 6px;
  padding: 1px 6px;
  font: 800 8.5px/1 'Inter', sans-serif;
  letter-spacing: 0.5px;
  color: #fff;
  background: #1565c0;
  border-radius: 3px;
  vertical-align: middle;
}
._eli3_help_announce_sum {
  font: 500 11px/1.45 'Inter', sans-serif;
  color: #475569;
  margin-top: 2px;
}
._eli3_help_announce_footer {
  display: flex;
  gap: 8px;
  align-items: center;
  margin-top: 4px;
}
._eli3_help_announce_status {
  font: 800 8.5px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  padding: 2px 6px;
  border-radius: 3px;
}
._eli3_status_open       { background: #fef3c7; color: #92400e; }
._eli3_status_inprogress { background: #dbeafe; color: #1e40af; }
._eli3_status_fixed,
._eli3_status_shipped    { background: #dcfce7; color: #166534; }
._eli3_status_wontfix    { background: #f1f5f9; color: #64748b; }
._eli3_help_announce_time {
  font: 500 10px/1 'Inter', sans-serif;
  color: #94a3b8;
}

/* ─── About tab — hero + credit + stats, no buttons ──────────────── */
._eli3_about_root {
  padding: 4px 2px 8px;
  text-align: center;
}
._eli3_about_hero {
  display: flex; align-items: center; justify-content: center; gap: 14px;
  margin-bottom: 14px;
}
._eli3_about_logo {
  width: 64px; height: 64px;
  display: inline-flex; align-items: center; justify-content: center;
  font-size: 36px;
  background: linear-gradient(135deg, #0d1b2a 0%, #1b263b 100%);
  color: #c9a227;
  border: 2px solid #c9a227;
  border-radius: 14px;
  box-shadow: 0 4px 12px rgba(15, 23, 42, 0.18);
}
._eli3_about_brand { text-align: left; }
._eli3_about_brand_name {
  font: 800 28px/1 'Book Antiqua', Georgia, serif;
  color: #0d1b2a;
  letter-spacing: 1px;
}
._eli3_about_brand_tag {
  font: 600 11px/1 'Inter', sans-serif;
  color: #c9a227;
  letter-spacing: 2px;
  text-transform: uppercase;
  margin-top: 4px;
}
._eli3_about_lead {
  font: 500 12px/1.55 'Inter', sans-serif;
  color: #475569;
  max-width: 460px;
  margin: 0 auto 16px;
}
._eli3_about_credit {
  padding: 12px 16px;
  margin: 0 auto 14px;
  max-width: 320px;
  background: linear-gradient(135deg, #fffbeb 0%, #fef3c7 100%);
  border: 1px solid #fcd34d;
  border-radius: 8px;
}
._eli3_about_credit_eyebrow {
  font: 800 9px/1 'Inter', sans-serif;
  letter-spacing: 1.4px;
  text-transform: uppercase;
  color: #92400e;
}
._eli3_about_credit_name {
  font: 800 16px/1.1 'Inter', sans-serif;
  color: #0f172a;
  margin-top: 4px;
}
._eli3_about_stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin-bottom: 14px;
}
._eli3_about_stat {
  padding: 8px 10px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 6px;
}
._eli3_about_stat_label {
  font: 700 9px/1 'Inter', sans-serif;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  color: #94a3b8;
}
._eli3_about_stat_value {
  font: 700 13px/1.2 'Inter', sans-serif;
  color: #0f172a;
  margin-top: 4px;
}
._eli3_about_userblock {
  padding: 10px 14px;
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 6px;
  display: inline-block;
  text-align: left;
  min-width: 240px;
}
._eli3_about_user_line {
  font: 700 12.5px/1.2 'Inter', sans-serif;
  color: #0f172a;
  margin-top: 3px;
}
._eli3_about_user_sub {
  font: 500 11px/1.3 'Inter', sans-serif;
  color: #64748b;
  margin-top: 2px;
}

/* 2026-05-13 item 12: feedback context hint */
._eli3_help_fb_context_hint {
  margin-top: 6px;
  font: 500 10.5px/1.4 'Inter', sans-serif;
  color: #64748b;
  padding: 6px 10px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-left: 3px solid #c9a227;
  border-radius: 4px;
}
._eli3_help_fb_context_hint em {
  color: #166534;
  font-style: normal;
  font-weight: 600;
}

/* ─── Cancelled screen (2026-05-16) ────────────────────────────────
   Fires on FSM transition → "cancelled". Premium navy scrim, floating
   card with gold accent, single Go Home action. Reads as a deliberate
   stopping point, not an error — matching the user's actual intent
   (they pressed Cancel). Esc dismisses too (handled in view.js). */
._eli3_cancelled_overlay {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;
  background: radial-gradient(ellipse at center,
    rgba(13, 27, 42, 0.92) 0%,
    rgba(13, 27, 42, 0.97) 70%,
    rgba(13, 27, 42, 0.99) 100%);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  animation: _eli3_cancelled_fade_in 0.22s ease-out;
}
@keyframes _eli3_cancelled_fade_in {
  from { opacity: 0; }
  to   { opacity: 1; }
}
._eli3_cancelled_card {
  position: relative;
  width: 380px;
  max-width: 92vw;
  padding: 36px 32px 28px;
  background: linear-gradient(180deg, #1b263b 0%, #243b5e 100%);
  border: 1px solid rgba(201, 162, 39, 0.45);
  border-top: 3px solid #c9a227;
  border-radius: 0; /* squared corners — matches the rest of v3's premium chrome */
  box-shadow:
    0 24px 60px rgba(0, 0, 0, 0.6),
    0 0 0 1px rgba(255, 255, 255, 0.04) inset,
    0 1px 0 rgba(255, 255, 255, 0.06) inset;
  text-align: center;
  animation: _eli3_cancelled_card_in 0.32s cubic-bezier(0.22, 1, 0.36, 1);
}
@keyframes _eli3_cancelled_card_in {
  from { transform: translateY(8px) scale(0.97); opacity: 0; }
  to   { transform: translateY(0) scale(1);     opacity: 1; }
}
._eli3_cancelled_card::before {
  /* Subtle gold sheen across the top edge — premium-card signature. */
  content: "";
  position: absolute;
  top: 0; left: 12%; right: 12%;
  height: 2px;
  background: linear-gradient(90deg, transparent, rgba(242, 216, 102, 0.85) 50%, transparent);
  pointer-events: none;
}
._eli3_cancelled_iconwrap {
  width: 64px;
  height: 64px;
  margin: 0 auto 18px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, #fdf3c4 0%, #f7e7a3 100%);
  border: 1px solid #c9a227;
  border-radius: 50%;
  box-shadow:
    0 4px 14px rgba(201, 162, 39, 0.32),
    inset 0 1px 0 rgba(255, 255, 255, 0.7);
}
._eli3_cancelled_icon {
  font-size: 28px;
  line-height: 1;
  color: #6b4f0a;
}
._eli3_cancelled_eyebrow {
  font: 800 10px/1 'Inter', sans-serif;
  letter-spacing: 1.6px;
  text-transform: uppercase;
  color: rgba(242, 216, 102, 0.9);
  margin-bottom: 10px;
}
._eli3_cancelled_title {
  font: 700 22px/1.25 'Book Antiqua', Georgia, serif;
  letter-spacing: 0.3px;
  color: #ffffff;
  margin-bottom: 10px;
}
._eli3_cancelled_subtitle {
  font: 400 13px/1.55 'Inter', sans-serif;
  color: rgba(255, 255, 255, 0.72);
  margin-bottom: 24px;
  padding: 0 6px;
}
._eli3_cancelled_btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-width: 160px;
  padding: 11px 26px;
  background: linear-gradient(180deg, #c9a227 0%, #a8841d 100%);
  border: 1px solid #c9a227;
  color: #1b263b;
  font: 800 11px/1 'Inter', sans-serif;
  letter-spacing: 1.1px;
  text-transform: uppercase;
  cursor: pointer;
  transition: transform 0.12s ease, box-shadow 0.18s ease, background 0.18s ease;
  box-shadow:
    0 6px 14px rgba(201, 162, 39, 0.35),
    inset 0 1px 0 rgba(255, 255, 255, 0.4);
}
._eli3_cancelled_btn:hover {
  background: linear-gradient(180deg, #d4af37 0%, #b8932a 100%);
  box-shadow:
    0 9px 22px rgba(201, 162, 39, 0.45),
    inset 0 1px 0 rgba(255, 255, 255, 0.55);
  transform: translateY(-1px);
}
._eli3_cancelled_btn:active {
  transform: translateY(0);
}
._eli3_cancelled_btn_icon {
  font-size: 14px;
  line-height: 1;
}
